/**
 * Policy Clause Templates — People & Awareness (p44-p46)
 * Based on ISO 27001:2022, BSI IT-Grundschutz, NIST CSF 2.0, NIS2 Art.21
 *
 * Delegation boundaries:
 * - p44: Canonical owner of all training, awareness, incident-reporting training
 * - p45: Behavioural acceptable-use rules; delegates BYOD→p23, Clean Desk→p25, Printing→p24, Network→p16
 * - p46: Remote-work security; delegates Endpoint→p17, Backup→p36, DSGVO→p37, Training→p44
 */
import type { PolicyClause } from "../policyClauseTemplates";

export const peopleAwarenessClauses: Record<string, PolicyClause[]> = {
  /* ═══════════════════════════════════════════════════════════
   *  p44 — Security Training & Awareness (18 clauses)
   *  Consolidated: c02+c08→Phishing&SE, c03+c14→Measurement, c07+c10→Engagement
   * ═══════════════════════════════════════════════════════════ */
  p44: [
    { id: "p44-c00", title: "Zweck und Geltungsbereich der Schulungsrichtlinie", titleEn: "Purpose & Scope of Training Policy", description: "Diese Richtlinie definiert den Rahmen für Sicherheitsbewusstsein und Schulungen aller Beschäftigten. NIS2 Art.20(2) bzw. § 38 BSIG verlangen ausdrücklich, dass die Leitungsorgane an Cybersicherheitsschulungen teilnehmen und allen Mitarbeitern Schulungen angeboten werden.", descriptionEn: "This policy defines the framework for security awareness and training of all employees. NIS2 Art.20(2) and § 38 BSIG explicitly require management to participate in cybersecurity training and all employees to be offered training.", reason: "Der Mensch ist die wichtigste Verteidigungslinie und gleichzeitig die häufigste Schwachstelle.", reasonEn: "Humans are both the most important line of defence and the most common vulnerability.", whenRequired: "Immer erforderlich als NIS2-Anforderung.", whenRequiredEn: "Always required as NIS2 requirement.", sources: ["NIS2 Art.20(2), Art.21(2)(g)", "§ 38 BSIG", "ISO 27001:2022 A.6.3", "BSI IT-Grundschutz ORP.3", "NIST CSF 2.0 PR.AT"] },
    { id: "p44-c01", title: "Schulungsprogramm und Jahresplan", titleEn: "Training Programme & Annual Plan", description: "Wir müssen ein umfassendes Sicherheitsschulungsprogramm mit jährlichem Schulungsplan entwickeln. Das Programm muss verschiedene Zielgruppen adressieren: alle Beschäftigten (Grundlagenschulungen), IT-Personal (technische Schulungen), Führungsebene (Governance und Verantwortung gemäß NIS2), privilegierte Nutzer (besondere Risiken) und neue Beschäftigte (Einführungsschulung).", descriptionEn: "We must develop a comprehensive security training programme with an annual training plan addressing: all employees (basic training), IT staff (technical training), management (governance and responsibility per NIS2), privileged users (special risks), and new employees (induction training).", reason: "Technische Maßnahmen allein sind nicht ausreichend. NIS2 Art.20(2) verlangt ausdrücklich Cyberhygiene-Schulungen.", reasonEn: "Technical measures alone are insufficient. NIS2 Art.20(2) explicitly mandates cyber hygiene training.", whenRequired: "Immer erforderlich. NIS2 verlangt Schulungen für alle einschließlich Leitung.", whenRequiredEn: "Always required. NIS2 mandates training for all including management.", sources: ["ISO 27001:2022 §7.2-7.3, A.6.3", "NIS2 Art.20(2)", "BSI IT-Grundschutz ORP.3", "NIST CSF 2.0 PR.AT"] },
    { id: "p44-c02", title: "Phishing-Simulationen, Social Engineering und Awareness-Tests", titleEn: "Phishing Simulations, Social Engineering & Awareness Tests", description: "Regelmäßig und risikobasiert (Richtwert: quartalsweise bis halbjährlich) müssen Phishing-Simulationen durchgeführt werden: E-Mail-Phishing, Spear-Phishing, SMS-Phishing und Voice-Phishing. Parallel müssen Beschäftigte über weitere Social-Engineering-Techniken aufgeklärt werden: Pretexting, Baiting, Tailgating, Quid-pro-quo-Angriffe und Impersonation. Verfahren zur Identitätsverifikation bei telefonischen und persönlichen Anfragen müssen definiert und geschult werden. Ergebnisse müssen anonymisiert ausgewertet und Nachschulungen für auffällige Bereiche durchgeführt werden.", descriptionEn: "Phishing simulations must be conducted regularly and risk-based (guideline: quarterly to semi-annually): email phishing, spear phishing, SMS phishing, and voice phishing. In parallel, employees must be educated about further social engineering techniques: pretexting, baiting, tailgating, quid-pro-quo attacks, and impersonation. Procedures for identity verification during phone and in-person requests must be defined and trained. Results must be evaluated anonymously and follow-up training conducted for conspicuous areas.", reason: "Phishing und Social Engineering sind die häufigsten Angriffsvektoren und umgehen technische Schutzmaßnahmen vollständig. Nur geschulte Beschäftigte können solche Angriffe erkennen.", reasonEn: "Phishing and social engineering are the most common attack vectors and completely bypass technical protective measures. Only trained employees can recognise such attacks.", whenRequired: "Immer erforderlich. Frequenz risikobasiert (Richtwert: quartalsweise bis halbjährlich).", whenRequiredEn: "Always required. Frequency risk-based (guideline: quarterly to semi-annually).", sources: ["ISO 27001:2022 A.6.3", "NIS2 Art.21(2)(g)", "BSI IT-Grundschutz ORP.3", "NIST CSF 2.0 PR.AT"] },
    { id: "p44-c03", title: "Schulungsnachweise, Wirksamkeitsmessung und Sicherheitskultur", titleEn: "Training Records, Effectiveness Measurement & Security Culture", description: "Die Teilnahme muss dokumentiert werden. Wirksamkeit muss durch messbare KPIs bewertet werden: Teilnahmequoten, Testergebnisse, Phishing-Simulationsergebnisse und Vorfallstatistiken. Bei nicht bestandenen Tests müssen Nachschulungen erfolgen. Ergänzend muss die Organisation regelmäßig die Sicherheitskultur messen: anonyme Mitarbeiterbefragungen, Analyse des Meldeverhaltens, Beobachtung des Sicherheitsverhaltens (z.B. Clean-Desk-Compliance). Ergebnisse müssen in die Strategie einfließen.", descriptionEn: "Participation must be documented. Effectiveness must be evaluated through measurable KPIs: participation rates, test results, phishing simulation results, and incident statistics. Failed tests require follow-up training. Additionally, we must regularly measure security culture: anonymous employee surveys, analysis of reporting behaviour, observation of security behaviour (e.g., clean desk compliance). Results must feed into strategy.", reason: "Ohne Wirksamkeitsmessung und Kulturanalyse kann die Organisation weder Compliance nachweisen noch die tatsächliche Wirkung des Awareness-Programms beurteilen.", reasonEn: "Without effectiveness measurement and culture analysis, we can neither demonstrate compliance nor assess the actual impact of the awareness programme.", whenRequired: "Immer erforderlich. Nachweise mindestens 3 Jahre aufbewahren.", whenRequiredEn: "Always required. Records must be retained at least 3 years.", sources: ["ISO 27001:2022 §7.2, §9.1", "NIS2 Art.20(2)", "BSI IT-Grundschutz ORP.3"] },
    { id: "p44-c04", title: "Onboarding-Sicherheitsschulung", titleEn: "Onboarding Security Training", description: "Neue Beschäftigte müssen vor Zugang zu Systemen eine Sicherheitseinführung absolvieren. Inhalte: Sicherheitsrichtlinien, Passworthygiene, Phishing-Erkennung, Vorfallmeldung, Acceptable Use und Datenschutz. Die Schulung muss durch Unterschrift bestätigt werden.", descriptionEn: "New employees must complete a security induction before system access. Content: security policies, password hygiene, phishing recognition, incident reporting, acceptable use, and data protection. Training must be confirmed by signature.", reason: "Neue Beschäftigte sind besonders gefährdet, da sie Prozesse und Risiken noch nicht kennen.", reasonEn: "New employees are particularly vulnerable as they do not yet know processes and risks.", whenRequired: "Erforderlich für alle neuen Beschäftigten.", whenRequiredEn: "Required for all new employees.", sources: ["ISO 27001:2022 A.6.3", "BSI IT-Grundschutz ORP.3", "NIST CSF 2.0 PR.AT"] },
    { id: "p44-c05", title: "Führungskräfte-Schulung (NIS2)", titleEn: "Management Training (NIS2)", description: "Leitungsorgane müssen gemäß NIS2 Art.20(2) bzw. § 38 BSIG an Cybersicherheitsschulungen teilnehmen. Inhalte: Cyberrisiken und deren Geschäftsauswirkungen, persönliche Haftung der Leitung, regulatorische Anforderungen, Krisenkommunikation und strategische Sicherheitsentscheidungen. Schulungen müssen mindestens jährlich stattfinden.", descriptionEn: "Management must participate in cybersecurity training per NIS2 Art.20(2) and § 38 BSIG. Content: cyber risks and business impacts, personal management liability, regulatory requirements, crisis communication, and strategic security decisions. Training must occur at least annually.", reason: "NIS2 macht die Leitung persönlich verantwortlich für Cybersicherheit.", reasonEn: "NIS2 makes management personally responsible for cybersecurity.", whenRequired: "Verpflichtend für alle NIS2-regulierten Organisationen.", whenRequiredEn: "Mandatory for all NIS2-regulated organisations.", sources: ["NIS2 Art.20(2)", "§ 38 BSIG", "ISO 27001:2022 §5.1", "BSI IT-Grundschutz ISMS.1"] },
    { id: "p44-c06", title: "Rollenbasierte Fachschulungen", titleEn: "Role-Based Technical Training", description: "IT-Personal und Sicherheitsteams müssen rollenspezifische technische Schulungen erhalten: Systemadministratoren (Härtung, Patch-Management), Entwickler (sichere Programmierung, OWASP Top 10), IRT-Mitglieder (Forensik, Incident Response), SOC-Analysten (SIEM, Bedrohungsanalyse). Zertifizierungen sollen gefördert werden.", descriptionEn: "IT staff and security teams must receive role-specific technical training: system administrators (hardening, patch management), developers (secure programming, OWASP Top 10), IRT members (forensics, incident response), SOC analysts (SIEM, threat analysis). Certifications should be promoted.", reason: "Allgemeine Schulungen reichen für technisches Personal nicht aus.", reasonEn: "General training is insufficient for technical staff.", whenRequired: "Erforderlich für alle technischen Sicherheitsrollen.", whenRequiredEn: "Required for all technical security roles.", sources: ["ISO 27001:2022 §7.2", "NIS2 Art.21(2)(g)", "BSI IT-Grundschutz ORP.3"] },
    { id: "p44-c07", title: "Awareness-Kampagnen, Gamification und Incentives", titleEn: "Awareness Campaigns, Gamification & Incentives", description: "Ergänzend zu formellen Schulungen müssen regelmäßige Awareness-Kampagnen durchgeführt werden: Poster, Intranet-Artikel, Newsletter, Screensaver-Nachrichten, Security Awareness Month und Wettbewerbe. Gamification-Elemente sollen integriert werden: Punktesysteme, Leaderboards, Badges für abgeschlossene Module und Wettbewerbe zwischen Abteilungen. Positive Anreize (z.B. Anerkennung, kleine Prämien) für vorbildliches Sicherheitsverhalten sollen gefördert werden.", descriptionEn: "Supplementing formal training, regular awareness campaigns must be conducted: posters, intranet articles, newsletters, screensaver messages, Security Awareness Month, and competitions. Gamification elements should be integrated: point systems, leaderboards, badges for completed modules, and competitions between departments. Positive incentives (e.g., recognition, small rewards) for exemplary security behaviour should be promoted.", reason: "Einmalige Schulungen werden schnell vergessen. Kontinuierliche, abwechslungsreiche Kampagnen mit spielerischen Elementen erhöhen die Beteiligung und festigen sicheres Verhalten nachhaltig (vgl. ENISA Awareness Raising Best Practices).", reasonEn: "One-time training is quickly forgotten. Continuous, varied campaigns with playful elements increase participation and sustainably reinforce secure behaviour (cf. ENISA Awareness Raising Best Practices).", whenRequired: "Empfohlen als Ergänzung zu formellen Schulungen.", whenRequiredEn: "Recommended to supplement formal training.", sources: ["ISO 27001:2022 A.6.3", "BSI IT-Grundschutz ORP.3", "NIST CSF 2.0 PR.AT", "ENISA Awareness Raising Best Practices"] },
    { id: "p44-c08", title: "Krisenübungen und Tabletop-Exercises", titleEn: "Crisis Exercises & Tabletop Exercises", description: "Regelmäßige Krisenübungen und Tabletop-Exercises müssen durchgeführt werden, um die Reaktionsfähigkeit der Organisation bei Sicherheitsvorfällen zu testen. Übungen müssen realistische Szenarien verwenden (z.B. Ransomware, Datenleck, DDoS) und alle relevanten Funktionen einbeziehen. Ergebnisse müssen dokumentiert und Lessons Learned umgesetzt werden.", descriptionEn: "Regular crisis exercises and tabletop exercises must be conducted to test the organisation's response capability for security incidents. Exercises must use realistic scenarios (e.g., ransomware, data leak, DDoS) and involve all relevant functions. Results must be documented and lessons learned implemented.", reason: "Theoretisches Wissen reicht in Krisensituationen nicht aus. Übungen schaffen Routine und decken Schwächen auf.", reasonEn: "Theoretical knowledge is insufficient in crisis situations. Exercises create routine and reveal weaknesses.", whenRequired: "Erforderlich mindestens jährlich für kritische Szenarien.", whenRequiredEn: "Required at least annually for critical scenarios.", sources: ["NIS2 Art.21(2)(c)", "ISO 27001:2022 A.5.30", "BSI IT-Grundschutz DER.4"] },
    { id: "p44-c09", title: "E-Learning-Plattform und digitale Schulungsinhalte", titleEn: "E-Learning Platform & Digital Training Content", description: "Wir müssen eine E-Learning-Plattform für Sicherheitsschulungen bereitstellen. Die Plattform muss selbstgesteuertes Lernen, Lernfortschrittsverfolgung, automatische Zuweisung von Pflichtschulungen und Reporting ermöglichen. Inhalte müssen interaktiv gestaltet sein und aktuelle Bedrohungsszenarien abbilden.", descriptionEn: "We must provide an e-learning platform for security training. The platform must enable self-paced learning, progress tracking, automatic assignment of mandatory training, and reporting. Content must be interactively designed and reflect current threat scenarios.", reason: "E-Learning ermöglicht flexible, skalierbare und nachweisbare Schulung auch für verteilte Organisationen.", reasonEn: "E-learning enables flexible, scalable, and demonstrable training even for distributed organisations.", whenRequired: "Empfohlen für alle Organisationen mit mehr als 50 Beschäftigten.", whenRequiredEn: "Recommended for all organisations with more than 50 employees.", sources: ["ISO 27001:2022 A.6.3", "BSI IT-Grundschutz ORP.3"] },
    { id: "p44-c10", title: "Bedrohungsspezifische Schulungsmodule", titleEn: "Threat-Specific Training Modules", description: "Zusätzlich zu allgemeinen Schulungen müssen bedrohungsspezifische Module bereitstehen: Ransomware-Prävention, CEO-Fraud/Business Email Compromise, Insider-Bedrohungen, USB-basierte Angriffe, QR-Code-Phishing und KI-gestützte Angriffe. Module müssen bei Auftreten neuer Bedrohungen zeitnah aktualisiert werden.", descriptionEn: "In addition to general training, threat-specific modules must be available: ransomware prevention, CEO fraud/business email compromise, insider threats, USB-based attacks, QR code phishing, and AI-powered attacks. Modules must be promptly updated when new threats emerge.", reason: "Generische Schulungen decken spezifische, aktuelle Bedrohungen nicht ausreichend ab.", reasonEn: "Generic training does not adequately cover specific, current threats.", whenRequired: "Empfohlen als Ergänzung zu Basisschulungen.", whenRequiredEn: "Recommended to supplement basic training.", sources: ["ISO 27001:2022 A.6.3", "NIS2 Art.21(2)(g)", "BSI IT-Grundschutz ORP.3"] },
    { id: "p44-c11", title: "Sicherheits-Champions-Programm", titleEn: "Security Champions Programme", description: "Wir sollen ein Security-Champions-Programm etablieren, bei dem ausgewählte Beschäftigte aus verschiedenen Abteilungen als Sicherheitsbotschafter fungieren. Champions erhalten erweiterte Schulungen, unterstützen bei der Sensibilisierung ihrer Kolleginnen und Kollegen und dienen als erste Anlaufstelle für Sicherheitsfragen.", descriptionEn: "We should establish a Security Champions programme where selected employees from various departments serve as security ambassadors. Champions receive enhanced training, support awareness efforts among colleagues, and serve as first point of contact for security questions.", reason: "Dezentrale Sicherheitsbotschafter erhöhen die Reichweite und Glaubwürdigkeit des Awareness-Programms.", reasonEn: "Decentralised security ambassadors increase the reach and credibility of the awareness programme.", whenRequired: "Empfohlen für Organisationen mit mehr als 100 Beschäftigten.", whenRequiredEn: "Recommended for organisations with more than 100 employees.", sources: ["ISO 27001:2022 A.6.3", "BSI IT-Grundschutz ORP.3"] },
    { id: "p44-c12", title: "Sprachliche und kulturelle Anpassung", titleEn: "Linguistic & Cultural Adaptation", description: "Schulungsinhalte müssen in allen relevanten Sprachen der Organisation verfügbar sein. Kulturelle Unterschiede in der Risikowahrnehmung und im Kommunikationsstil müssen berücksichtigt werden. Für Beschäftigte mit eingeschränkten Sprachkenntnissen müssen alternative Formate (z.B. visuelle Anleitungen, Videos mit Untertiteln) bereitgestellt werden.", descriptionEn: "Training content must be available in all relevant languages of the organisation. Cultural differences in risk perception and communication style must be considered. For employees with limited language skills, alternative formats (e.g., visual guides, videos with subtitles) must be provided.", reason: "Schulungen, die nicht verstanden werden, sind wirkungslos.", reasonEn: "Training that is not understood is ineffective.", whenRequired: "Erforderlich für mehrsprachige Organisationen.", whenRequiredEn: "Required for multilingual organisations.", sources: ["ISO 27001:2022 A.6.3", "BSI IT-Grundschutz ORP.3"] },
    { id: "p44-c13", title: "Externe Schulungsteilnahme und Konferenzbesuche", titleEn: "External Training & Conference Attendance", description: "Wir müssen ein Budget und einen Prozess für die Teilnahme an externen Sicherheitsschulungen und -konferenzen bereitstellen. Priorität haben: Zertifizierungsschulungen (CISSP, CISM, ISO 27001 Lead Auditor), Fachkonferenzen und herstellerspezifische Schulungen für eingesetzte Sicherheitstechnologien.", descriptionEn: "We must provide a budget and process for participation in external security training and conferences. Priority for: certification training (CISSP, CISM, ISO 27001 Lead Auditor), specialised conferences, and vendor-specific training for deployed security technologies.", reason: "Interne Schulungen allein halten nicht mit der sich schnell entwickelnden Bedrohungslandschaft Schritt.", reasonEn: "Internal training alone cannot keep pace with the rapidly evolving threat landscape.", whenRequired: "Empfohlen für alle Sicherheitsteam-Mitglieder.", whenRequiredEn: "Recommended for all security team members.", sources: ["ISO 27001:2022 §7.2", "BSI IT-Grundschutz ORP.3"] },
    { id: "p44-c14", title: "Vorfallmeldungs-Schulung (kanonisch)", titleEn: "Incident Reporting Training (Canonical)", description: "Alle Beschäftigten müssen geschult werden, wie sie Sicherheitsvorfälle und verdächtige Aktivitäten melden — im Büro, im Homeoffice und unterwegs. Schulungsinhalte: Was ist meldepflichtig, wie und an wen wird gemeldet (auch außerhalb des Unternehmensnetzwerks), Schutz für Meldende (keine Sanktionen für gutgläubige Meldungen), Zeitanforderungen, Remote-spezifische Szenarien (Geräteverlust → Remote-Löschung) und Beispiele aus der Praxis. Diese Klausel ist die kanonische Quelle; p45 und p46 verweisen hierher.", descriptionEn: "All employees must be trained on how to report security incidents and suspicious activities — in office, at home, and on the go. Training content: what must be reported, how and to whom (also outside the corporate network), protection for reporters (no sanctions for good-faith reports), time requirements, remote-specific scenarios (device loss → remote wipe), and practical examples. This clause is the canonical source; p45 and p46 cross-reference here.", reason: "Beschäftigte erkennen oft Anomalien, melden sie aber nicht, weil sie nicht wissen wie oder Angst vor Konsequenzen haben. Remote-Kontext erfordert besondere Meldewege.", reasonEn: "Employees often detect anomalies but do not report them because they do not know how or fear consequences. Remote context requires special reporting channels.", whenRequired: "Immer erforderlich für alle Beschäftigten.", whenRequiredEn: "Always required for all employees.", sources: ["NIS2 Art.23", "ISO 27001:2022 A.6.8", "BSI IT-Grundschutz DER.2.1"] },
    { id: "p44-c15", title: "Datenschutz-Schulungen (DSGVO)", titleEn: "Data Protection Training (GDPR)", description: "Ergänzend zu Sicherheitsschulungen müssen spezifische Datenschutzschulungen durchgeführt werden. Inhalte: DSGVO-Grundsätze, Rechte der Betroffenen, Umgang mit Datenschutzanfragen, Meldepflichten bei Datenpannen, Privacy-by-Design und sichere Datenverarbeitung.", descriptionEn: "Supplementing security training, specific data protection training must be conducted. Content: GDPR principles, data subject rights, handling data protection requests, breach notification obligations, privacy-by-design, and secure data processing.", reason: "Datenschutzschulungen sind eine gesetzliche Pflicht und ergänzen die Informationssicherheitsschulungen.", reasonEn: "Data protection training is a legal obligation and complements information security training.", whenRequired: "Immer erforderlich gemäß DSGVO.", whenRequiredEn: "Always required per GDPR.", sources: ["DSGVO Art.39(1)(b)", "ISO 27001:2022 A.5.34", "BSI IT-Grundschutz CON.2"] },
    { id: "p44-c16", title: "Auftragnehmer- und Zeitarbeitskräfte-Schulung", titleEn: "Contractor & Temporary Staff Training", description: "Externe Auftragnehmer und Zeitarbeitskräfte müssen vor Zugang zu Organisationsressourcen eine Sicherheitseinführung absolvieren. Der Umfang richtet sich nach der Art des Zugangs und der Vertraulichkeit der Informationen. Schulungsteilnahme muss vertraglich verpflichtend und dokumentiert sein.", descriptionEn: "External contractors and temporary staff must complete a security induction before accessing organisation resources. The scope depends on the type of access and confidentiality of information. Training participation must be contractually mandatory and documented.", reason: "Externe Kräfte haben oft Zugang zu sensiblen Bereichen, kennen aber die Sicherheitsrichtlinien der Organisation nicht.", reasonEn: "External staff often have access to sensitive areas but do not know the organisation's security policies.", whenRequired: "Erforderlich für alle externen Kräfte mit Systemzugang.", whenRequiredEn: "Required for all external staff with system access.", sources: ["ISO 27001:2022 A.6.6", "BSI IT-Grundschutz ORP.3", "NIS2 Art.21(2)(g)"] },
    { id: "p44-c17", title: "Schulungsbudget, Ressourcenplanung und Überprüfung", titleEn: "Training Budget, Resource Planning & Review", description: "Wir müssen ein angemessenes Budget für Sicherheitsschulungen bereitstellen und jährlich planen. Richtwerte: mindestens 2-5% des IT-Sicherheitsbudgets. Budget muss E-Learning-Lizenzen, externe Schulungen, Konferenzbesuche, Simulationstools und interne Schulungsentwicklung abdecken. Diese Richtlinie muss mindestens jährlich überprüft und aktualisiert werden. Aktuelle Bedrohungstrends, Schulungsfeedback und Awareness-Test-Ergebnisse müssen in die Aktualisierung einfließen.", descriptionEn: "We must provide and annually plan an appropriate budget for security training. Benchmarks: at least 2-5% of IT security budget. Budget must cover e-learning licences, external training, conference attendance, simulation tools, and internal training development. This policy must be reviewed and updated at least annually. Current threat trends, training feedback, and awareness test results must feed into updates.", reason: "Ohne Budget und regelmäßige Überprüfung kann kein wirksames Schulungsprogramm aufrechterhalten werden.", reasonEn: "Without budget and regular review, no effective training programme can be maintained.", whenRequired: "Erforderlich für eine wirksame Schulungsstrategie.", whenRequiredEn: "Required for an effective training strategy.", sources: ["ISO 27001:2022 §7.1, §10.1-10.2", "NIS2 Art.20(1)", "BSI IT-Grundschutz ORP.3"] },
  ],

  /* ═══════════════════════════════════════════════════════════
   *  p45 — Acceptable Use Policy (17 clauses)
   *  Consolidated: c08+c18→Sanctions, c10+c14→Media
   *  Delegated: Clean Desk→p25, BYOD→p23, Printing→p24, Network→p16, Incident→p44-c14
   * ═══════════════════════════════════════════════════════════ */
  p45: [
    { id: "p45-c00", title: "Zweck und Geltungsbereich der Acceptable Use Policy", titleEn: "Purpose & Scope of Acceptable Use Policy", description: "Diese Richtlinie definiert die akzeptable Nutzung aller IT-Ressourcen der Organisation (Computer, Netzwerke, E-Mail, Internet, Cloud-Dienste, mobile Geräte). Sie gilt für alle Beschäftigten, Auftragnehmer und Dritte mit Zugang zu IT-Ressourcen.", descriptionEn: "This policy defines the acceptable use of all IT resources (computers, networks, email, internet, cloud services, mobile devices). It applies to all employees, contractors, and third parties with IT resource access.", reason: "Ohne klare Nutzungsregeln können IT-Ressourcen missbräuchlich oder unsicher genutzt werden.", reasonEn: "Without clear usage rules, IT resources can be misused or used insecurely.", whenRequired: "Immer erforderlich für alle IT-Nutzer.", whenRequiredEn: "Always required for all IT users.", sources: ["ISO 27001:2022 A.5.10", "BSI IT-Grundschutz ORP.4", "NIST CSF 2.0 PR.AT"] },
    { id: "p45-c01", title: "Erlaubte und verbotene Nutzung", titleEn: "Permitted & Prohibited Use", description: "IT-Ressourcen dürfen primär für geschäftliche Zwecke genutzt werden. Begrenzte private Nutzung kann gestattet sein, sofern sie die Arbeit nicht beeinträchtigt. Ausdrücklich verboten sind: illegale Aktivitäten, Zugriff auf unangemessene Inhalte, Installation nicht genehmigter Software, Weiterleitung vertraulicher Daten an private Konten und Nutzung nicht genehmigter Cloud-Dienste.", descriptionEn: "IT resources may primarily be used for business purposes. Limited private use may be permitted if it does not affect work. Explicitly prohibited: illegal activities, accessing inappropriate content, installing unapproved software, forwarding confidential data to private accounts, and using unapproved cloud services.", reason: "Klare Regeln verhindern Missbrauch und schaffen Rechtssicherheit für beide Seiten.", reasonEn: "Clear rules prevent misuse and create legal certainty for both sides.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.5.10", "BSI IT-Grundschutz ORP.4"] },
    { id: "p45-c02", title: "Internet- und E-Mail-Nutzung", titleEn: "Internet & Email Use", description: "Internetnutzung muss den Sicherheitsrichtlinien entsprechen. Downloads aus unbekannten Quellen sind verboten. E-Mail darf nicht für die Übertragung STRENG VERTRAULICHER Daten ohne Verschlüsselung genutzt werden. Weiterleitungsregeln an externe Adressen sind eingeschränkt. Phishing-verdächtige E-Mails müssen gemeldet werden.", descriptionEn: "Internet use must comply with security policies. Downloads from unknown sources are prohibited. Email must not be used for transmitting STRICTLY CONFIDENTIAL data without encryption. Forwarding rules to external addresses are restricted. Phishing-suspicious emails must be reported.", reason: "Internet und E-Mail sind primäre Angriffsvektoren.", reasonEn: "Internet and email are primary attack vectors.", whenRequired: "Erforderlich für alle Internet- und E-Mail-Nutzer.", whenRequiredEn: "Required for all internet and email users.", sources: ["ISO 27001:2022 A.5.10", "BSI IT-Grundschutz APP.5.3", "NIST CSF 2.0 PR.AT"] },
    { id: "p45-c03", title: "Software und Schatten-IT", titleEn: "Software & Shadow IT", description: "Software darf nur aus genehmigten Quellen installiert werden. Die Nutzung nicht genehmigter SaaS-Dienste (Schatten-IT) ist verboten. Beschäftigte müssen neue Softwareanforderungen über den IT-Service-Desk einreichen. Die IT-Abteilung muss einen Prozess für schnelle Software-Freigabe bereitstellen.", descriptionEn: "Software may only be installed from approved sources. Use of unapproved SaaS services (shadow IT) is prohibited. Employees must submit new software requirements through the IT service desk. IT must provide a process for rapid software approval.", reason: "Nicht genehmigte Software kann Sicherheitslücken und Compliance-Verstöße verursachen.", reasonEn: "Unapproved software can cause security gaps and compliance violations.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.19", "BSI IT-Grundschutz APP.6", "NIST CSF 2.0 PR.DS"] },
    { id: "p45-c04", title: "Passwort- und Authentifizierungspflichten", titleEn: "Password & Authentication Obligations", description: "Beschäftigte müssen starke Passwörter verwenden und dürfen diese nicht teilen. MFA muss für alle kritischen Systeme aktiviert sein. Passwortmanager werden empfohlen. Passwörter dürfen nicht unverschlüsselt gespeichert oder per E-Mail versendet werden. Technische Details zu Passwortregeln und MFA-Methoden sind in p13 (Passwortverwaltung) und p11 (Identität & Authentifizierung) definiert.", descriptionEn: "Employees must use strong passwords and must not share them. MFA must be activated for all critical systems. Password managers are recommended. Passwords must not be stored unencrypted or sent by email. Technical details on password rules and MFA methods are defined in p13 (Password Management) and p11 (Identity & Authentication).", reason: "Schwache oder geteilte Passwörter sind der häufigste Angriffsvektor für Kontenkompromittierung.", reasonEn: "Weak or shared passwords are the most common attack vector for account compromise.", whenRequired: "Immer erforderlich für alle Nutzer.", whenRequiredEn: "Always required for all users.", sources: ["ISO 27001:2022 A.8.5", "BSI IT-Grundschutz ORP.4", "NIST CSF 2.0 PR.AA"] },
    { id: "p45-c05", title: "BYOD-Verhaltensregeln (Querverweis p23)", titleEn: "BYOD Behavioural Rules (Cross-ref p23)", description: "Beschäftigte, die private Geräte für geschäftliche Zwecke nutzen, müssen die BYOD-Regeln einhalten. Grundregeln: keine geschäftlichen Daten auf nicht genehmigten privaten Geräten, Meldung bei Geräteverlust. Technische BYOD-Anforderungen (MDM, Verschlüsselung, OS-Versionen) sind kanonisch in p23 (MDM & BYOD) definiert.", descriptionEn: "Employees using private devices for business purposes must comply with BYOD rules. Basic rules: no business data on unapproved private devices, report device loss. Technical BYOD requirements (MDM, encryption, OS versions) are canonically defined in p23 (MDM & BYOD).", reason: "Private Geräte ohne Sicherheitskontrollen stellen ein erhebliches Risiko für Unternehmensdaten dar.", reasonEn: "Private devices without security controls pose a significant risk to corporate data.", whenRequired: "Erforderlich sofern BYOD gestattet ist.", whenRequiredEn: "Required if BYOD is permitted.", sources: ["ISO 27001:2022 A.8.1", "BSI IT-Grundschutz SYS.3.2.1", "Querverweis: p23"] },
    { id: "p45-c06", title: "Cloud- und KI-Nutzung", titleEn: "Cloud & AI Usage", description: "Die Nutzung von Cloud-Diensten und KI-Tools muss den genehmigten Diensten entsprechen. Geschäftsdaten dürfen nicht in nicht genehmigte Cloud-Dienste oder KI-Tools eingegeben werden. Die Eingabe vertraulicher oder personenbezogener Daten in öffentliche KI-Dienste ist verboten.", descriptionEn: "Use of cloud services and AI tools must correspond to approved services. Business data must not be entered into unapproved cloud services or AI tools. Entry of confidential or personal data into public AI services is prohibited.", reason: "Unkontrollierte Cloud- und KI-Nutzung kann zu Datenverlust und Compliance-Verstößen führen.", reasonEn: "Uncontrolled cloud and AI usage can lead to data loss and compliance violations.", whenRequired: "Erforderlich für alle Cloud- und KI-Nutzer.", whenRequiredEn: "Required for all cloud and AI users.", sources: ["ISO 27001:2022 A.5.23", "EU AI Act", "BSI IT-Grundschutz OPS.1.1.6"] },
    { id: "p45-c07", title: "Social-Media-Nutzung", titleEn: "Social Media Usage", description: "Die Nutzung sozialer Medien am Arbeitsplatz muss geregelt sein. Beschäftigte dürfen keine vertraulichen Geschäftsinformationen in sozialen Medien teilen. Die dienstliche Nutzung sozialer Medien erfordert Genehmigung. Beschäftigte müssen über Social-Engineering-Risiken in sozialen Medien aufgeklärt werden.", descriptionEn: "Social media use at the workplace must be regulated. Employees must not share confidential business information on social media. Business use of social media requires approval. Employees must be educated about social engineering risks on social media.", reason: "Soziale Medien sind ein häufiger Kanal für Informationslecks und Social-Engineering-Angriffe.", reasonEn: "Social media is a common channel for information leaks and social engineering attacks.", whenRequired: "Erforderlich für alle Beschäftigten.", whenRequiredEn: "Required for all employees.", sources: ["ISO 27001:2022 A.5.10", "BSI IT-Grundschutz ORP.4"] },
    { id: "p45-c08", title: "Wechseldatenträger und persönliche Speichermedien", titleEn: "Removable Media & Personal Storage Devices", description: "Die Nutzung von USB-Sticks, externen Festplatten, SD-Karten und anderen Wechseldatenträgern muss stark eingeschränkt werden. Nur genehmigte, verschlüsselte Datenträger dürfen verwendet werden. Die Verwendung persönlicher externer Speichermedien an Organisationsgeräten ist grundsätzlich untersagt. Gefundene oder geschenkte USB-Sticks dürfen nicht an Organisationsgeräte angeschlossen werden. USB-Ports können technisch gesperrt werden. DLP-Mechanismen müssen die Durchsetzung unterstützen.", descriptionEn: "Use of USB drives, external hard drives, SD cards, and other removable media must be strongly restricted. Only approved, encrypted media may be used. Use of personal external storage media on organisation devices is generally prohibited. Found or gifted USB drives must not be connected to organisation devices. USB ports can be technically blocked. DLP mechanisms must support enforcement.", reason: "Wechseldatenträger und persönliche Speichermedien sind häufige Vektoren für Malware-Infektionen, Datendiebstahl und unkontrollierten Datenabfluss.", reasonEn: "Removable media and personal storage devices are frequent vectors for malware infections, data theft, and uncontrolled data exfiltration.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.7.10, A.8.12", "BSI IT-Grundschutz SYS.4.5", "NIST CSF 2.0 PR.DS"] },
    { id: "p45-c09", title: "Datenspeicherung und -übertragung", titleEn: "Data Storage & Transfer", description: "Geschäftsdaten dürfen nur auf genehmigten Speichersystemen gespeichert werden. Die Übertragung vertraulicher Daten auf private Geräte, nicht genehmigte Cloud-Dienste oder USB-Sticks ist ohne Genehmigung verboten. Genehmigte Datentransfermethoden müssen definiert und kommuniziert werden.", descriptionEn: "Business data may only be stored on approved storage systems. Transfer of confidential data to private devices, unapproved cloud services, or USB drives is prohibited without approval. Approved data transfer methods must be defined and communicated.", reason: "Unkontrollierte Datenspeicherung und -übertragung sind Hauptursachen für Datenverlust.", reasonEn: "Uncontrolled data storage and transfer are primary causes of data loss.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.12", "BSI IT-Grundschutz ORP.4", "NIST CSF 2.0 PR.DS"] },
    { id: "p45-c10", title: "Meldepflicht für Sicherheitsereignisse (Querverweis p44-c14)", titleEn: "Security Event Reporting Obligation (Cross-ref p44-c14)", description: "Beschäftigte sind verpflichtet, alle sicherheitsrelevanten Ereignisse unverzüglich zu melden: verdächtige E-Mails, unbekannte Personen in gesicherten Bereichen, ungewöhnliches Systemverhalten, Verlust oder Diebstahl von Geräten, vermutete Datenschutzverletzungen. Die Meldung muss über definierte Kanäle erfolgen. Detaillierte Schulungsinhalte zu Vorfallmeldung sind kanonisch in p44-c14 definiert.", descriptionEn: "Employees are obligated to immediately report all security-relevant events: suspicious emails, unknown persons in secured areas, unusual system behaviour, loss or theft of devices, suspected data protection violations. Reports must be made through defined channels. Detailed training content on incident reporting is canonically defined in p44-c14.", reason: "Frühzeitige Meldung ist entscheidend für schnelle Reaktion und Schadensbegrenzung.", reasonEn: "Early reporting is crucial for rapid response and damage limitation.", whenRequired: "Immer erforderlich für alle Beschäftigten.", whenRequiredEn: "Always required for all employees.", sources: ["NIS2 Art.23", "ISO 27001:2022 A.6.8", "BSI IT-Grundschutz DER.2.1", "Querverweis: p44-c14"] },
    { id: "p45-c11", title: "Nutzung privater Kommunikationsdienste", titleEn: "Use of Private Communication Services", description: "Die Verwendung privater Messaging-Dienste (WhatsApp, Telegram, Signal etc.) für geschäftliche Kommunikation ist verboten, sofern keine organisationsspezifische Genehmigung vorliegt. Geschäftliche Kommunikation muss über von der Organisation bereitgestellte und verwaltete Kanäle erfolgen.", descriptionEn: "Use of private messaging services (WhatsApp, Telegram, Signal etc.) for business communication is prohibited unless organisation-specific approval exists. Business communication must take place through organisation-provided and managed channels.", reason: "Private Kommunikationsdienste unterliegen nicht der Kontrolle der Organisation.", reasonEn: "Private communication services are not under organisation control.", whenRequired: "Erforderlich für alle Beschäftigten.", whenRequiredEn: "Required for all employees.", sources: ["ISO 27001:2022 A.5.10", "DSGVO Art.32", "BSI IT-Grundschutz APP.5.3"] },
    { id: "p45-c12", title: "Verantwortung für IT-Vermögenswerte", titleEn: "IT Asset Responsibility", description: "Beschäftigte sind für die ihnen zugewiesenen IT-Vermögenswerte (Laptops, Smartphones, Tokens) verantwortlich. Geräte müssen pfleglich behandelt, gegen Diebstahl geschützt und bei Verlust sofort gemeldet werden. Bei Austritt müssen alle Vermögenswerte vollständig zurückgegeben werden.", descriptionEn: "Employees are responsible for IT assets assigned to them (laptops, smartphones, tokens). Devices must be handled with care, protected against theft, and loss must be immediately reported. All assets must be fully returned upon departure.", reason: "Verlorene oder gestohlene IT-Vermögenswerte können vertrauliche Daten exponieren.", reasonEn: "Lost or stolen IT assets can expose confidential data.", whenRequired: "Immer erforderlich für alle Beschäftigten mit IT-Vermögenswerten.", whenRequiredEn: "Always required for all employees with IT assets.", sources: ["ISO 27001:2022 A.5.9-5.11", "BSI IT-Grundschutz ORP.4"] },
    { id: "p45-c13", title: "Clean Desk, Drucken und physische Sicherheit (Querverweis p24, p25)", titleEn: "Clean Desk, Printing & Physical Security (Cross-ref p24, p25)", description: "Beschäftigte müssen ihren Arbeitsplatz aufgeräumt halten, Bildschirmsperre bei Verlassen aktivieren und vertrauliche Dokumente sicher verwahren. Das Drucken vertraulicher Dokumente muss auf das notwendige Minimum beschränkt werden; Secure-Print ist zu verwenden. Physische Sicherheitsverantwortung umfasst: Türen schließen, Besucher begleiten, Tailgating verhindern und Sicherheitskarten nicht verleihen. Detaillierte technische Anforderungen zu Clean Desk sind in p25, zu Druckinfrastruktur in p24 definiert.", descriptionEn: "Employees must keep workspaces tidy, activate screen lock when leaving, and securely store confidential documents. Printing of confidential documents must be minimised; secure print must be used. Physical security responsibilities include: closing doors, escorting visitors, preventing tailgating, and not lending security cards. Detailed technical requirements for clean desk are in p25, for print infrastructure in p24.", reason: "Offene Dokumente, ungesperrte Bildschirme und unkontrolliertes Drucken ermöglichen unbefugten Zugriff.", reasonEn: "Open documents, unlocked screens, and uncontrolled printing enable unauthorised access.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.7.7-7.10", "BSI IT-Grundschutz INF.1", "DIN 66399", "Querverweis: p24, p25"] },
    { id: "p45-c14", title: "Nutzung von Videokonferenzsystemen", titleEn: "Video Conferencing System Usage", description: "Die Nutzung von Videokonferenzsystemen muss den Sicherheitsrichtlinien entsprechen. Nur genehmigte Systeme dürfen verwendet werden. Vertrauliche Meetings müssen mit Warteraum und Passwortschutz durchgeführt werden. Bildschirmfreigabe muss kontrolliert erfolgen. Aufzeichnungen müssen genehmigt und sicher gespeichert werden.", descriptionEn: "Use of video conferencing systems must comply with security policies. Only approved systems may be used. Confidential meetings must use waiting rooms and password protection. Screen sharing must be controlled. Recordings must be approved and securely stored.", reason: "Videokonferenzen können unbeabsichtigt vertrauliche Informationen exponieren.", reasonEn: "Video conferences can unintentionally expose confidential information.", whenRequired: "Erforderlich für alle Videokonferenz-Nutzer.", whenRequiredEn: "Required for all video conference users.", sources: ["ISO 27001:2022 A.5.10", "BSI IT-Grundschutz APP.5.3"] },
    { id: "p45-c15", title: "Netzwerkzugangsregeln (Querverweis p16)", titleEn: "Network Access Rules (Cross-ref p16)", description: "Beschäftigte dürfen nur über genehmigte Netzwerkzugänge auf IT-Ressourcen zugreifen. Die Nutzung öffentlicher WLANs ohne VPN ist verboten. Tethering und mobile Hotspots müssen genehmigt werden. Technische Netzwerkarchitektur, NAC und 802.1X sind kanonisch in p16 (Netzwerksicherheit) definiert.", descriptionEn: "Employees may only access IT resources via approved network connections. Use of public WiFi without VPN is prohibited. Tethering and mobile hotspots must be approved. Technical network architecture, NAC, and 802.1X are canonically defined in p16 (Network Security).", reason: "Unkontrollierter Netzwerkzugang gefährdet die Vertraulichkeit und Integrität der Kommunikation.", reasonEn: "Uncontrolled network access compromises the confidentiality and integrity of communication.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.20-8.22", "BSI IT-Grundschutz NET.1.1", "Querverweis: p16"] },
    { id: "p45-c16", title: "Konsequenzen und Sanktionen bei Verstößen", titleEn: "Consequences & Sanctions for Violations", description: "Verstöße gegen die Acceptable Use Policy müssen Konsequenzen haben. Ein abgestuftes Sanktionssystem ist definiert: Ermahnung und Nachschulung, temporärer Zugangsentzug, arbeitsrechtliche Maßnahmen (Abmahnung, Kündigung). Vorsätzliche Verstöße werden strenger behandelt als fahrlässige. Strafrechtliche Verfolgung bei illegalen Aktivitäten wird nicht ausgeschlossen. Beschäftigte müssen bei Onboarding über Sanktionen informiert werden. Diese Richtlinie muss mindestens jährlich überprüft und aktualisiert werden.", descriptionEn: "Violations of the Acceptable Use Policy must have consequences. A graduated sanctions system is defined: warning and re-training, temporary access revocation, employment law measures (formal warning, termination). Intentional violations are treated more severely than negligent ones. Criminal prosecution for illegal activities is not excluded. Employees must be informed about sanctions during onboarding. This policy must be reviewed and updated at least annually.", reason: "Ohne definierte Konsequenzen und Durchsetzung verliert jede Richtlinie ihre Wirksamkeit.", reasonEn: "Without defined consequences and enforcement, any policy loses its effectiveness.", whenRequired: "Immer erforderlich als Teil der Richtlinie.", whenRequiredEn: "Always required as part of the policy.", sources: ["ISO 27001:2022 A.5.4, A.6.4, §10.1-10.2", "BSI IT-Grundschutz ORP.1, ORP.4"] },
  ],

  /* ═══════════════════════════════════════════════════════════
   *  p46 — Remote Work & Mobile Security (18 clauses)
   *  Consolidated: c01+c09→VPN/ZeroTrust
   *  Delegated: Endpoint→p17, Backup→p36, DSGVO→p37, Training→p44, Incident→p44-c14
   * ═══════════════════════════════════════════════════════════ */
  p46: [
    { id: "p46-c00", title: "Zweck und Geltungsbereich der Remote-Work-Richtlinie", titleEn: "Purpose & Scope of Remote Work Policy", description: "Diese Richtlinie definiert die Sicherheitsanforderungen für mobiles Arbeiten, Homeoffice und Telearbeit. Sie gilt für alle Beschäftigten und Auftragnehmer, die außerhalb der Büroräume der Organisation arbeiten.", descriptionEn: "This policy defines security requirements for mobile working, home office, and telework. It applies to all employees and contractors working outside office premises.", reason: "Remote-Arbeit erhöht die Angriffsfläche erheblich.", reasonEn: "Remote work significantly increases the attack surface.", whenRequired: "Erforderlich für alle Organisationen mit Remote-Work.", whenRequiredEn: "Required for all organisations with remote work.", sources: ["ISO 27001:2022 A.6.7", "BSI IT-Grundschutz OPS.1.2.4", "NIST CSF 2.0 PR.DS"] },
    { id: "p46-c01", title: "VPN, Zero-Trust-Architektur und Netzwerksicherheit", titleEn: "VPN, Zero Trust Architecture & Network Security", description: "Remote-Zugriff auf Unternehmensressourcen muss über VPN oder Zero-Trust-Netzwerkzugang (ZTNA) erfolgen. Öffentliche WLANs dürfen nur mit VPN genutzt werden. Split-Tunneling muss deaktiviert sein. Die VPN-Lösung muss MFA erfordern und aktuelle Verschlüsselungsstandards unterstützen. Zero-Trust-Prinzipien sollen implementiert werden: Jeder Zugriff wird unabhängig vom Netzwerkstandort verifiziert, kontextbasierte Zugriffsentscheidungen (Gerätegesundheit, Standort, Zeitpunkt), Mikrosegmentierung und kontinuierliche Authentifizierung.", descriptionEn: "Remote access to corporate resources must use VPN or Zero Trust Network Access (ZTNA). Public WiFi may only be used with VPN. Split tunnelling must be disabled. The VPN solution must require MFA and support current encryption standards. Zero Trust principles should be implemented: every access verified regardless of network location, context-based access decisions (device health, location, time), micro-segmentation, and continuous authentication.", reason: "Ungesicherte Netzwerkverbindungen ermöglichen das Abfangen von Daten. Klassische VPN-Ansätze gewähren oft zu breiten Zugang; Zero Trust minimiert die Angriffsfläche.", reasonEn: "Unsecured network connections enable data interception. Classic VPN approaches often grant too broad access; Zero Trust minimises the attack surface.", whenRequired: "Erforderlich für alle Remote-Zugriffe.", whenRequiredEn: "Required for all remote access.", sources: ["ISO 27001:2022 A.8.24", "BSI IT-Grundschutz NET.3.3", "NIST SP 800-207", "NIST CSF 2.0 PR.DS"] },
    { id: "p46-c02", title: "Homeoffice-Arbeitsplatz-Sicherheit", titleEn: "Home Office Workplace Security", description: "Der Heimarbeitsplatz muss Mindestsicherheitsstandards erfüllen: abschließbarer Raum oder Schrank für vertrauliche Unterlagen, Sichtschutz für den Bildschirm, sichere WLAN-Konfiguration (WPA3), Trennung von privater und geschäftlicher Nutzung und Schutz vor unbefugtem Zugriff durch Mitbewohner.", descriptionEn: "The home workplace must meet minimum security standards: lockable room or cabinet for confidential documents, screen privacy filter, secure WiFi configuration (WPA3), separation of private and business use, and protection against unauthorised access by household members.", reason: "Im Homeoffice fehlen die physischen Schutzmaßnahmen des Büros.", reasonEn: "Home offices lack the physical protective measures of the office.", whenRequired: "Erforderlich für alle Homeoffice-Arbeitsplätze.", whenRequiredEn: "Required for all home office workplaces.", sources: ["ISO 27001:2022 A.6.7", "BSI IT-Grundschutz INF.8", "NIST CSF 2.0 PR.DS"] },
    { id: "p46-c03", title: "Geräte- und Datenschutz unterwegs", titleEn: "Device & Data Protection On-the-Go", description: "Bei mobilem Arbeiten (Reisen, öffentliche Orte) gelten erhöhte Sicherheitsanforderungen: Geräte nie unbeaufsichtigt lassen, Sichtschutzfolie verwenden, keine vertraulichen Gespräche in Hörweite Dritter, automatische Bildschirmsperre und verschlüsselte Datenträger verwenden.", descriptionEn: "Enhanced security requirements apply for mobile working (travel, public places): never leave devices unattended, use privacy screen filters, no confidential conversations within earshot of third parties, use automatic screen lock, and encrypted storage media.", reason: "Mobiles Arbeiten in öffentlichen Umgebungen birgt erhöhte Risiken durch visuelle und akustische Spionage.", reasonEn: "Mobile working in public environments carries increased risks from visual and acoustic espionage.", whenRequired: "Erforderlich für alle mobil Arbeitenden.", whenRequiredEn: "Required for all mobile workers.", sources: ["ISO 27001:2022 A.6.7, A.7.9", "BSI IT-Grundschutz SYS.3.1"] },
    { id: "p46-c04", title: "Drucken und Papierdokumente im Homeoffice", titleEn: "Printing & Paper Documents in Home Office", description: "Das Drucken vertraulicher Dokumente im Homeoffice muss minimiert werden. Gedruckte vertrauliche Dokumente müssen sicher aufbewahrt und per Aktenvernichter (mindestens DIN 66399 P-4) vernichtet werden. Der Transport vertraulicher Papierunterlagen zwischen Büro und Homeoffice muss in verschlossenen Behältnissen erfolgen.", descriptionEn: "Printing of confidential documents in home office must be minimised. Printed confidential documents must be stored securely and destroyed using a shredder (at least DIN 66399 P-4). Transport of confidential paper documents between office and home office must use locked containers.", reason: "Papierunterlagen im Homeoffice sind besonders gefährdet.", reasonEn: "Paper documents in home offices are particularly vulnerable.", whenRequired: "Erforderlich für alle Beschäftigten im Homeoffice.", whenRequiredEn: "Required for all employees in home office.", sources: ["ISO 27001:2022 A.7.10", "BSI IT-Grundschutz INF.8", "DIN 66399"] },
    { id: "p46-c05", title: "Kommunikationstools für Remote-Arbeit", titleEn: "Communication Tools for Remote Work", description: "Wir müssen genehmigte Kommunikationstools für Remote-Arbeit bereitstellen: Videokonferenz-Systeme, Messaging-Plattformen und Collaboration-Tools. Nicht genehmigte Tools dürfen nicht für geschäftliche Kommunikation genutzt werden. Vertrauliche Meetings müssen über verschlüsselte Plattformen mit Zugangskontrolle (Warteraum, Passwort) durchgeführt werden.", descriptionEn: "We must provide approved communication tools for remote work: video conferencing, messaging platforms, and collaboration tools. Unapproved tools must not be used for business communication. Confidential meetings must use encrypted platforms with access control (waiting room, password).", reason: "Unkontrollierte Kommunikationstools können zu Datenverlust und Compliance-Verstößen führen.", reasonEn: "Uncontrolled communication tools can lead to data loss and compliance violations.", whenRequired: "Erforderlich für alle Remote-Arbeitenden.", whenRequiredEn: "Required for all remote workers.", sources: ["ISO 27001:2022 A.5.14", "BSI IT-Grundschutz OPS.1.2.4"] },
    { id: "p46-c06", title: "Vorfallmeldung und Geräteverlust (Querverweis p44-c14)", titleEn: "Incident Reporting & Device Loss (Cross-ref p44-c14)", description: "Beschäftigte müssen wissen, wie sie Sicherheitsvorfälle auch aus dem Homeoffice melden können. Meldewege müssen auch außerhalb des Unternehmensnetzwerks zugänglich sein. Bei Geräteverlust oder -diebstahl muss eine sofortige Meldung erfolgen, damit Remote-Löschung eingeleitet werden kann. Umfassende Schulungsinhalte zur Vorfallmeldung sind kanonisch in p44-c14 definiert.", descriptionEn: "Employees must know how to report security incidents from home office. Reporting channels must be accessible outside the corporate network. For device loss or theft, immediate reporting must occur so remote wipe can be initiated. Comprehensive training content on incident reporting is canonically defined in p44-c14.", reason: "Im Remote-Kontext können Vorfälle leicht unbemerkt bleiben oder verspätet gemeldet werden.", reasonEn: "In a remote context, incidents can easily go unnoticed or be reported late.", whenRequired: "Erforderlich für alle Remote-Arbeitenden.", whenRequiredEn: "Required for all remote workers.", sources: ["ISO 27001:2022 A.6.8", "BSI IT-Grundschutz DER.2.1", "Querverweis: p44-c14"] },
    { id: "p46-c07", title: "Endpoint-Security für Remote-Geräte (Querverweis p17)", titleEn: "Endpoint Security for Remote Devices (Cross-ref p17)", description: "Alle Remote-Geräte müssen Endpoint-Detection-and-Response (EDR), aktuelle Patches, Host-Firewall, Festplattenverschlüsselung und automatische Sicherheitsupdates haben. Der Compliance-Status muss über MDM/UEM kontinuierlich überwacht werden. Nicht-konforme Geräte müssen automatisch vom Zugang ausgeschlossen werden. Detaillierte Endpoint-Sicherheitsstandards sind kanonisch in p17 (Endpoint Security) definiert.", descriptionEn: "All remote devices must have EDR, current patches, host firewall, disk encryption, and automatic security updates. Compliance status must be continuously monitored via MDM/UEM. Non-compliant devices must be automatically excluded from access. Detailed endpoint security standards are canonically defined in p17 (Endpoint Security).", reason: "Remote-Geräte sind stärker gefährdet als Bürogeräte, da sie sich außerhalb des geschützten Netzwerks befinden.", reasonEn: "Remote devices are more vulnerable than office devices as they are outside the protected network.", whenRequired: "Erforderlich für alle Remote-Geräte.", whenRequiredEn: "Required for all remote devices.", sources: ["ISO 27001:2022 A.8.1", "BSI IT-Grundschutz SYS.3.2.1", "Querverweis: p17"] },
    { id: "p46-c08", title: "Remote-Arbeitsplatz-Genehmigungsverfahren", titleEn: "Remote Workplace Approval Process", description: "Vor der dauerhaften Einrichtung eines Homeoffice-Arbeitsplatzes muss ein Genehmigungsverfahren durchlaufen werden. Der Arbeitsplatz muss auf Sicherheitsanforderungen überprüft werden. Eine Checkliste für Mindestanforderungen muss ausgefüllt und dokumentiert werden.", descriptionEn: "Before permanently setting up a home office workplace, an approval process must be completed. The workplace must be checked for security requirements. A checklist for minimum requirements must be completed and documented.", reason: "Ohne Genehmigungsverfahren können unsichere Arbeitsumgebungen unbemerkt bleiben.", reasonEn: "Without an approval process, insecure work environments can go unnoticed.", whenRequired: "Erforderlich für alle dauerhaften Remote-Arbeitsplätze.", whenRequiredEn: "Required for all permanent remote workplaces.", sources: ["ISO 27001:2022 A.6.7", "BSI IT-Grundschutz INF.8"] },
    { id: "p46-c09", title: "Internationales Remote-Arbeiten", titleEn: "International Remote Working", description: "Arbeiten aus dem Ausland muss gesondert genehmigt werden. Datenschutzrechtliche Implikationen (Datenübermittlung in Drittländer), steuerliche Aspekte, lokale Sicherheitsrisiken und regulatorische Anforderungen müssen bewertet werden. Zugriff aus Hochrisikoländern kann eingeschränkt oder blockiert werden.", descriptionEn: "Working from abroad must be separately approved. Data protection implications (data transfers to third countries), tax aspects, local security risks, and regulatory requirements must be assessed. Access from high-risk countries can be restricted or blocked.", reason: "Internationales Arbeiten kann Datenschutz- und Compliance-Risiken erzeugen.", reasonEn: "International working can create data protection and compliance risks.", whenRequired: "Erforderlich für alle Organisationen mit internationalem Remote-Arbeiten.", whenRequiredEn: "Required for all organisations with international remote working.", sources: ["DSGVO Art.44-49", "ISO 27001:2022 A.6.7"] },
    { id: "p46-c10", title: "Backup und Datensicherung bei Remote-Arbeit (Querverweis p36)", titleEn: "Backup & Data Protection for Remote Work (Cross-ref p36)", description: "Daten auf Remote-Geräten müssen automatisch in die zentrale Backup-Infrastruktur eingebunden sein. Lokale Datenspeicherung muss minimiert werden. Cloud-basierte Arbeitslaufwerke sind zu bevorzugen. Beschäftigte müssen darüber informiert sein, welche Daten gesichert werden und welche nicht. Technische Backup-Infrastruktur, 3-2-1-Regel und Retention-Logik sind kanonisch in p36 (Backup Policy) definiert.", descriptionEn: "Data on remote devices must be automatically integrated into the central backup infrastructure. Local data storage must be minimised. Cloud-based work drives are preferred. Employees must be informed which data is backed up and which is not. Technical backup infrastructure, 3-2-1 rule, and retention logic are canonically defined in p36 (Backup Policy).", reason: "Lokale Daten auf Remote-Geräten gehen bei Defekt oder Verlust ohne Backup unwiederbringlich verloren.", reasonEn: "Local data on remote devices is irrecoverably lost in case of defect or loss without backup.", whenRequired: "Erforderlich für alle Remote-Geräte.", whenRequiredEn: "Required for all remote devices.", sources: ["ISO 27001:2022 A.8.13", "BSI IT-Grundschutz CON.3", "Querverweis: p36"] },
    { id: "p46-c11", title: "Ergonomie und Gesundheitsschutz im Homeoffice", titleEn: "Ergonomics & Health Protection in Home Office", description: "Wir müssen Mindestanforderungen an die ergonomische Gestaltung des Homeoffice-Arbeitsplatzes definieren und ggf. Zuschüsse für ergonomische Ausstattung gewähren. Gesundheitsschutz umfasst auch Pausenregelungen und Erreichbarkeitszeiten, um Überarbeitung zu vermeiden.", descriptionEn: "We must define minimum requirements for ergonomic home office setup and potentially provide subsidies for ergonomic equipment. Health protection also includes break regulations and availability times to prevent overwork.", reason: "Gesundheitsschutz ist eine Arbeitgeberpflicht, die auch im Homeoffice gilt.", reasonEn: "Health protection is an employer obligation that also applies in home offices.", whenRequired: "Erforderlich gemäß Arbeitsschutzgesetz.", whenRequiredEn: "Required per occupational health legislation.", sources: ["ArbSchG", "ISO 27001:2022 A.6.7", "BSI IT-Grundschutz INF.8"] },
    { id: "p46-c12", title: "Hybride Arbeitsmodelle und Übergänge", titleEn: "Hybrid Working Models & Transitions", description: "Für hybride Arbeitsmodelle (Wechsel zwischen Büro und Homeoffice) müssen klare Sicherheitsregeln definiert sein: sichere Mitnahme von Geräten und Dokumenten, Synchronisation von Daten über sichere Cloud-Dienste, keine vertraulichen Dokumente in öffentlichen Verkehrsmitteln lesen und VPN-Nutzung beim Übergang zwischen Netzwerken.", descriptionEn: "For hybrid working models (alternating between office and home), clear security rules must be defined: secure transport of devices and documents, data synchronisation via secure cloud services, no reading confidential documents on public transport, and VPN use when transitioning between networks.", reason: "Übergänge zwischen Büro und Homeoffice schaffen spezifische Sicherheitsrisiken.", reasonEn: "Transitions between office and home create specific security risks.", whenRequired: "Erforderlich für alle hybriden Arbeitsmodelle.", whenRequiredEn: "Required for all hybrid working models.", sources: ["ISO 27001:2022 A.6.7", "BSI IT-Grundschutz OPS.1.2.4"] },
    { id: "p46-c13", title: "IT-Support für Remote-Arbeitende", titleEn: "IT Support for Remote Workers", description: "Wir müssen IT-Support-Kanäle bereitstellen, die auch für Remote-Arbeitende zugänglich sind: Remote-Desktop-Support, Telefonhotline, Chat-Support und Self-Service-Portal. Sicherheitsrelevante Probleme müssen priorisiert behandelt werden. Remote-Support-Sitzungen müssen sicher durchgeführt werden.", descriptionEn: "We must provide IT support channels accessible to remote workers: remote desktop support, phone hotline, chat support, and self-service portal. Security-relevant problems must be treated with priority. Remote support sessions must be conducted securely.", reason: "Ohne erreichbaren IT-Support umgehen Remote-Arbeitende Sicherheitsmaßnahmen.", reasonEn: "Without reachable IT support, remote workers bypass security measures.", whenRequired: "Erforderlich für alle Organisationen mit Remote-Arbeit.", whenRequiredEn: "Required for all organisations with remote work.", sources: ["ISO 27001:2022 A.6.7", "BSI IT-Grundschutz OPS.1.2.4"] },
    { id: "p46-c14", title: "Remote-Work-Schulungen (Querverweis p44)", titleEn: "Remote Work Training (Cross-ref p44)", description: "Beschäftigte müssen spezifisch für die Sicherheitsrisiken des Remote-Arbeitens geschult werden: VPN-Nutzung, WLAN-Sicherheit, Phishing-Erkennung im Homeoffice, physische Sicherheit, Umgang mit vertraulichen Gesprächen und Vorfallmeldung. Die Schulung muss vor Beginn der Remote-Arbeit erfolgen. Die allgemeine Schulungsstrategie, E-Learning-Plattform und Wirksamkeitsmessung sind kanonisch in p44 definiert.", descriptionEn: "Employees must be specifically trained on security risks of remote working: VPN usage, WiFi security, phishing recognition in home office, physical security, handling confidential conversations, and incident reporting. Training must occur before starting remote work. The general training strategy, e-learning platform, and effectiveness measurement are canonically defined in p44.", reason: "Remote-Arbeit erfordert zusätzliches Sicherheitswissen, das in allgemeinen Schulungen nicht ausreichend abgedeckt wird.", reasonEn: "Remote work requires additional security knowledge not adequately covered in general training.", whenRequired: "Erforderlich für alle neuen Remote-Arbeitenden.", whenRequiredEn: "Required for all new remote workers.", sources: ["ISO 27001:2022 A.6.3, A.6.7", "BSI IT-Grundschutz ORP.3", "Querverweis: p44"] },
    { id: "p46-c15", title: "Datenschutz im Homeoffice (Querverweis p37)", titleEn: "Data Protection in Home Office (Cross-ref p37)", description: "Die DSGVO-Anforderungen müssen auch im Homeoffice vollständig eingehalten werden. Personenbezogene Daten dürfen nicht auf privaten Geräten oder in nicht genehmigten Cloud-Diensten verarbeitet werden. Dokumente mit personenbezogenen Daten müssen sicher aufbewahrt und entsorgt werden. Umfassende Datenschutzanforderungen, Breach-Management und DPIA-Logik sind kanonisch in p37 (Data Protection) definiert.", descriptionEn: "GDPR requirements must be fully met in home offices as well. Personal data must not be processed on private devices or in unapproved cloud services. Documents with personal data must be securely stored and disposed of. Comprehensive data protection requirements, breach management, and DPIA logic are canonically defined in p37 (Data Protection).", reason: "Im Homeoffice ist die Einhaltung der DSGVO schwieriger zu kontrollieren.", reasonEn: "In home offices, GDPR compliance is more difficult to control.", whenRequired: "Erforderlich für alle Remote-Arbeitenden mit Zugang zu personenbezogenen Daten.", whenRequiredEn: "Required for all remote workers with access to personal data.", sources: ["DSGVO Art.32", "ISO 27001:2022 A.5.34", "BSI IT-Grundschutz CON.2", "Querverweis: p37"] },
    { id: "p46-c16", title: "Notfall- und Krisenmanagement, Monitoring und Coworking", titleEn: "Emergency & Crisis Management, Monitoring & Coworking", description: "Notfall- und Krisenpläne müssen für Remote-Arbeitsszenarien angepasst sein. Kommunikationswege und Erreichbarkeiten müssen auch bei Ausfall der normalen Infrastruktur funktionieren. Wenn Remote-Aktivitäten überwacht werden (z.B. Netzwerk-Monitoring, Endpoint-Telemetrie), müssen die datenschutzrechtlichen Grenzen beachtet und Beschäftigte informiert werden. Der Betriebsrat muss einbezogen werden. Die Nutzung von Coworking-Spaces muss genehmigt werden mit zusätzlichen Anforderungen: Sichtschutzfolie, VPN-Pflicht, keine vertraulichen Gespräche in offenen Bereichen.", descriptionEn: "Emergency and crisis plans must be adapted for remote work scenarios. Communication channels must function even when normal infrastructure fails. When remote activities are monitored (e.g., network monitoring, endpoint telemetry), data protection limits must be observed and employees informed. Works council must be involved. Use of coworking spaces must be approved with additional requirements: privacy screen, VPN mandatory, no confidential conversations in open areas.", reason: "Verteilte Teams erfordern angepasste Krisenkommunikation, transparentes Monitoring und klare Regeln für externe Arbeitsplätze.", reasonEn: "Distributed teams require adapted crisis communication, transparent monitoring, and clear rules for external workplaces.", whenRequired: "Erforderlich für alle Organisationen mit Remote-Arbeit.", whenRequiredEn: "Required for all organisations with remote work.", sources: ["ISO 27001:2022 A.5.29-5.30, A.6.7", "BSI IT-Grundschutz DER.4, INF.8", "DSGVO Art.5-6", "BetrVG §87(1)(6)"] },
    { id: "p46-c17", title: "Netzwerksegmentierung im Heimnetz und Überprüfung", titleEn: "Home Network Segmentation & Policy Review", description: "Beschäftigte sollen ihr Heimnetzwerk segmentieren, um das Arbeitsgerät von privaten IoT-Geräten und Smart-Home-Systemen zu trennen. Die IT-Abteilung muss Anleitungen für die Einrichtung eines separaten WLANs oder VLANs bereitstellen. Diese Richtlinie muss mindestens jährlich überprüft und aktualisiert werden. Neue Technologien, veränderte Arbeitsmodelle und Erfahrungen müssen berücksichtigt werden.", descriptionEn: "Employees should segment their home network to separate work devices from private IoT devices and smart home systems. IT must provide guides for setting up a separate WiFi or VLAN. This policy must be reviewed and updated at least annually. New technologies, changed work models, and experiences must be considered.", reason: "Unsichere IoT-Geräte im selben Netzwerk können als Einstiegspunkt für Angriffe dienen. Regelmäßige Überprüfung stellt Aktualität sicher.", reasonEn: "Insecure IoT devices on the same network can serve as entry points for attacks. Regular review ensures currency.", whenRequired: "Empfohlen für alle Homeoffice-Arbeitsplätze. Überprüfung jährlich.", whenRequiredEn: "Recommended for all home office workplaces. Review annually.", sources: ["NIST SP 800-207", "BSI IT-Grundschutz NET.1.1", "ISO 27001:2022 A.8.22, §10.1-10.2"] },
  ],
};
